tinymce.PluginManager.add('fm', function (editor, url) {
    const openFileManager = () => {
        fileManager.init((res) => {
            tinymce.activeEditor.setContent(tinymce.activeEditor.getContent() + `<img src="/uf${res}" />`);
        });
    };

    editor.ui.registry.addButton('fm', {
        onAction: function (api) {
            openFileManager();
        },
        icon: 'image'
    });

    editor.ui.registry.addMenuItem('fm', {
        onAction: function (api) {
            openFileManager();
        },
        text: 'Изображение',
        icon: 'image'
    });

    return {
        getMetadata: function () {
            return {
                name: 'FileManager',
                url: 'https://github.com/growtask/simflex-file-manager',
            };
        }
    };
});
